def sha256(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def _guard(name: str, data: bytes) -> None:
    if len(data) != SIZES[name]:
        raise ValueError(f"{name}: size {len(data)} != expected {SIZES[name]}")
    got = sha256(data)
    if got != V12_HASHES[name]:
        raise ValueError(
            f"{name}: input SHA-256 {got} does not match exact public v1.2 "
            f"{V12_HASHES[name]}"
        )


def _patch_ranges(data: bytes, patches, label: str) -> bytes:
    out = bytearray(data)
    for off, old_hex, new_hex in patches:
        old = bytes.fromhex(old_hex)
        new = bytes.fromhex(new_hex)
        if len(old) != len(new):
            raise RuntimeError(f"{label} patch at {off:#x} changes file length")
        got = bytes(out[off:off + len(old)])
        if got != old:
            raise RuntimeError(
                f"{label} guard failed at {off:#x}: "
                f"got {got.hex()}, expected {old.hex()}"
            )
        out[off:off + len(new)] = new
    return bytes(out)


def _xor_delta(data: bytes, encoded: str, label: str) -> bytes:
    delta = zlib.decompress(base64.b85decode(encoded.encode("ascii")))
    if len(delta) != len(data):
        raise RuntimeError(f"{label} XOR delta length mismatch")
    return bytes(a ^ b for a, b in zip(data, delta))


def build_component(name: str, source: bytes) -> bytes:
    """Transform one exact v1.2 component into its exact v1.3 counterpart."""
    _guard(name, source)
    if name == "SLPM_658.82":
        out = _patch_ranges(source, EXE_PATCHES, name)
    elif name == "SCRPACK.SDA":
        out = _patch_ranges(source, SCR_PATCHES, name)
    elif name == "TCHANGE.IMG":
        out = _xor_delta(source, TCHANGE_XOR_B85, name)
    elif name == "DECK.DAT":
        out = _xor_delta(source, DECK_XOR_B85, name)
    else:
        raise KeyError(name)

    got = sha256(out)
    if got != V13_HASHES[name]:
        raise RuntimeError(
            f"{name}: v1.3 output SHA-256 {got} != expected {V13_HASHES[name]}"
        )
    if len(out) != len(source):
        raise RuntimeError(f"{name}: output size changed")
    return out


def main() -> None:
    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument(
        "v12_dir", type=Path,
        help="directory containing exact public-v1.2 SLPM_658.82, SCRPACK.SDA, TCHANGE.IMG, DECK.DAT",
    )
    ap.add_argument("output_dir", type=Path, help="directory for v1.3 component outputs")
    ap.add_argument("--report", type=Path, help="optional QA report path")
    args = ap.parse_args()

    args.output_dir.mkdir(parents=True, exist_ok=True)
    lines = ["BOTSD v1.3 MAINTENANCE COMPONENT BUILD", "source=public v1.2"]

    for name in V12_HASHES:
        src_path = args.v12_dir / name
        if not src_path.is_file():
            raise SystemExit(f"Missing input: {src_path}")
        source = src_path.read_bytes()
        target = build_component(name, source)
        out_path = args.output_dir / name
        out_path.write_bytes(target)
        lines.append(
            f"{name}: {V12_HASHES[name]} -> {V13_HASHES[name]} "
            f"({len(target)} bytes)"
        )

    lines += [
        "SLPM_658.82 containment=Aura Pegasus boundary + keyboard default byte only",
        "SCRPACK.SDA containment=3 probability branches + 1 confirmed dialogue line only",
        "TCHANGE.IMG containment=verified CHANGE/TURN geometry asset only",
        "DECK.DAT containment=DECK_SRC_DC_P02_TGA ACE badge only",
        "RESULT=PASS",
    ]
    report = "\n".join(lines) + "\n"
    print(report, end="")
    if args.report:
        args.report.parent.mkdir(parents=True, exist_ok=True)
        args.report.write_text(report, encoding="utf-8")


if __name__ == "__main__":
    main()
